  dynamic? voice=null;dynamic? stream=null;try{voice=Activator.CreateInstance(Type.GetTypeFromProgID("SAPI.SpVoice")!);var voices=voice!.GetVoices();bool english=false;for(int i=0;i<voices.Count;i++){dynamic token=voices.Item(i);string desc=token.GetDescription();if(desc.Contains("English",StringComparison.OrdinalIgnoreCase)){voice.Voice=token;english=true;break;}}if(!english)throw new InvalidOperationException("لا يوجد صوت إنجليزي مثبت. أضف صوتًا من إعدادات الكلام في Windows أو اختر ElevenLabs.");stream=Activator.CreateInstance(Type.GetTypeFromProgID("SAPI.SpFileStream")!);stream!.Open(path,3,false);voice.AudioOutputStream=stream;voice.Rate=slow?-3:0;voice.Volume=100;voice.Speak(text,0);stream.Close();}
  catch{if(File.Exists(path))File.Delete(path);throw;}finally{if(stream!=null){try{stream.Close();}catch{}Marshal.FinalReleaseComObject(stream);}if(voice!=null)Marshal.FinalReleaseComObject(voice);}}
